<?php require '_init.php';$pageTitle='Order management';$errors=[];if(post()){verify_csrf();$id=number('id');$status=textval('status');try{db()->beginTransaction();$o=query('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch();if(!$o||!in_array($status,status_options($o['status']),true))throw new RuntimeException('This status change is not allowed.');if($status==='Cancelled'){foreach(query('SELECT product_id,quantity FROM order_items WHERE order_id=? ORDER BY product_id',[$id])->fetchAll() as $item)query('UPDATE products SET stock=stock+? WHERE id=?',[$item['quantity'],$item['product_id']]);}query('UPDATE orders SET status=? WHERE id=?',[$status,$id]);db()->commit();flash('Order updated.');redirect('admin/orders.php?id='.$id);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$errors[]=$e instanceof PDOException?'Could not update order. Try again.':$e->getMessage();}}$id=number('id',true);$filter=textval('status',true);$params=[];$sql='SELECT * FROM orders';if($id){$sql.=' WHERE id=?';$params[]=$id;}elseif(in_array($filter,['Pending','Confirmed','Shipped','Delivered','Cancelled'],true)){$sql.=' WHERE status=?';$params[]=$filter;}$orders=query($sql.' ORDER BY id DESC',$params)->fetchAll();require '../includes/header.php';?><section class="container section"><h1>Orders</h1><?php errors($errors);?><form method="get" class="inline-form"><label>Status<select name="status"><option value="">All orders</option><?php foreach(['Pending','Confirmed','Shipped','Delivered','Cancelled'] as $s):?><option <?=$filter===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></label><button class="outline">Filter</button></form><?php if(!$orders)echo '<p class="panel">No orders found.</p>';foreach($orders as $o):?><article class="panel order"><div class="section-head"><h2>Order #<?=$o['id']?></h2><span class="badge"><?=e($o['status'])?></span></div><p><?=e($o['customer_name'].' · '.$o['email'].' · '.$o['phone'])?></p><p class="muted"><?=e($o['address'])?><br><?=e($o['created_at'])?> · Cash on delivery</p><div class="table-wrap"><table><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=$item['quantity']?></td><td><?=money($item['unit_price'])?></td><td><?=money($item['unit_price']*$item['quantity'])?></td></tr><?php endforeach;?></tbody></table></div><p>Delivery <?=money($o['shipping'])?> · <b>Total <?=money($o['total'])?></b></p><?php $options=status_options($o['status']);if($options):?><form method="post" class="inline-form"><?php csrf();?><input type="hidden" name="id" value="<?=$o['id']?>"><label>Next status<select name="status"><?php foreach($options as $s):?><option><?=$s?></option><?php endforeach;?></select></label><button>Update status</button></form><?php endif;?></article><?php endforeach;?></section><?php require '../includes/footer.php';?>
